function severityLabel(index, tier) {
  if (tier === 'POSITIVE' || tier === 'NEUTRAL') return index >= 25 ? 'Low' : 'None';
  if (index >= 70) return 'Critical';
  if (index >= 50) return 'High';
  if (index >= 25) return 'Medium';
  return 'Low';
